import asyncio
import sys

import pytest

pytest.importorskip("mcp", reason="MCP SDK not installed")

from gepa.adapters.mcp_adapter.mcp_client import StdioMCPClient


@pytest.fixture
def notification_server(tmp_path):
    script = tmp_path / "notification_server.py"
    script.write_text(
        """import json
import sys

count = int(sys.argv[1])
for line in sys.stdin:
    request = json.loads(line)
    if "id" not in request:
        continue
    if request["method"] == "initialize":
        print(json.dumps({
            "jsonrpc": "2.0", "id": request["id"], "result": {
                "protocolVersion": request["params"]["protocolVersion"],
                "capabilities": {"logging": {}, "tools": {}},
                "serverInfo": {"name": "notification-test-server", "version": "1.0"}
            }
        }), flush=True)
        continue
    for _ in range(count):
        print(json.dumps({
            "jsonrpc": "2.0", "method": "notifications/message",
            "params": {"level": "info", "data": "tool evaluation in progress"}
        }), flush=True)
    if request["method"] == "tools/call" and request["params"]["name"] == "unknown":
        response = {"error": {"code": -32602, "message": "invalid tool arguments"}}
    elif request["method"] == "tools/list":
        response = {"result": {"tools": [{
            "name": "read_file", "inputSchema": {"type": "object", "properties": {"path": {"type": "string"}}}
        }]}}
    else:
        response = {"result": {"content": [{
            "type": "text", "text": request["params"]["arguments"]["path"]
        }]}}
    print(json.dumps({"jsonrpc": "2.0", "id": request["id"], **response}), flush=True)
""",
        encoding="utf-8",
    )
    return script


@pytest.mark.parametrize("notification_count", [0, 1, 3])
def test_stdio_request_ignores_notifications_and_keeps_responses_in_order(notification_server, notification_count):
    async def exercise():
        client = StdioMCPClient(sys.executable, [str(notification_server), str(notification_count)])
        await client.start()
        try:
            await asyncio.wait_for(client.initialize(), timeout=5)
            first = await asyncio.wait_for(client.send_request("tools/list"), timeout=5)
            assert first["tools"][0]["name"] == "read_file"

            arguments = {"name": "read_file", "arguments": {"path": "notes.txt"}}
            second = await asyncio.wait_for(client.send_request("tools/call", arguments), timeout=5)
            assert second == {"content": [{"type": "text", "text": "notes.txt"}]}
        finally:
            await asyncio.wait_for(client.close(), timeout=5)
        assert client.process.returncode == 0

    asyncio.run(exercise())


def test_stdio_error_after_notification_propagates_and_does_not_poison_next_request(notification_server):
    async def exercise():
        client = StdioMCPClient(sys.executable, [str(notification_server), "1"])
        await client.start()
        try:
            await asyncio.wait_for(client.initialize(), timeout=5)
            with pytest.raises(Exception, match="MCP error.*invalid tool arguments"):
                await asyncio.wait_for(client.call_tool("unknown", {}), timeout=5)
            tools = await asyncio.wait_for(client.list_tools(), timeout=5)
            assert tools[0]["name"] == "read_file"
        finally:
            await asyncio.wait_for(client.close(), timeout=5)
        assert client.process.returncode == 0

    asyncio.run(exercise())

"""Validation evaluation policy protocols and helpers."""

from __future__ import annotations

from abc import abstractmethod
from typing import Protocol, runtime_checkable

from gepa.core.data_loader import DataId, DataInst, DataLoader
from gepa.core.state import GEPAState, ProgramIdx


@runtime_checkable
class EvaluationPolicy(Protocol[DataId, DataInst]):  # type: ignore
    """Strategy for choosing validation ids to evaluate and identifying best programs for validation instances."""

    @abstractmethod
    def get_eval_batch(
        self, loader: DataLoader[DataId, DataInst], state: GEPAState, target_program_idx: ProgramIdx | None = None
    ) -> list[DataId]:
        """Select examples for evaluation for a program"""
        ...

    @abstractmethod
    def get_best_program(self, state: GEPAState) -> ProgramIdx:
        """Return "best" program given all validation results so far across candidates"""
        ...

    @abstractmethod
    def get_valset_score(self, program_idx: ProgramIdx, state: GEPAState) -> float:
        """Return the score of the program on the valset"""
        ...


class FullEvaluationPolicy(EvaluationPolicy[DataId, DataInst]):
    """Policy that evaluates all validation instances every time."""

    def get_eval_batch(
        self, loader: DataLoader[DataId, DataInst], state: GEPAState, target_program_idx: ProgramIdx | None = None
    ) -> list[DataId]:
        """Always return the full ordered list of validation ids."""
        return list(loader.all_ids())

    def get_best_program(self, state: GEPAState) -> ProgramIdx:
        """Pick the program whose evaluated validation scores achieve the highest average."""
        best_idx, best_score, best_coverage = -1, float("-inf"), -1
        for program_idx, scores in enumerate(state.prog_candidate_val_subscores):
            coverage = len(scores)
            avg = sum(scores.values()) / coverage if coverage else float("-inf")
            if avg > best_score or (avg == best_score and coverage > best_coverage):
                best_score = avg
                best_idx = program_idx
                best_coverage = coverage
        return best_idx

    def get_valset_score(self, program_idx: ProgramIdx, state: GEPAState) -> float:
        """Return the score of the program on the valset"""
        return state.get_program_average_val_subset(program_idx)[0]


__all__ = [
    "DataLoader",
    "EvaluationPolicy",
    "FullEvaluationPolicy",
]

"""Check for Weights & Biases credentials."""

import os
from netrc import NetrcParseError, netrc


def has_wandb_credentials() -> bool:
    """Return True if W&B credentials are available via env var or ~/.netrc."""
    if os.environ.get("WANDB_API_KEY"):
        return True
    return _netrc_has_wandb_entry()


def _netrc_has_wandb_entry() -> bool:
    netrc_path = os.path.expanduser("~/.netrc")
    if not os.path.exists(netrc_path):
        return False
    try:
        nrc = netrc(netrc_path)
    except (NetrcParseError, OSError):
        return False
    for host in ("api.wandb.ai", "wandb.ai"):
        auth = nrc.authenticators(host)
        if auth is not None and auth[2]:  # auth[2] is the password/token
            return True
    return False

